# Run locally after installing or updating custom nodes with ComfyUI-Manager:
#   python colab/build.py
# Pins every node in custom_nodes/ to its Comfy Registry version in
# colab/custom_nodes.lock, combines their requirements into colab/requirements.txt
# and checks that it resolves for Colab. Commit both files.

import os
import subprocess
import tomllib

from install import CUSTOM_NODES, NODES_LOCK, REQUIREMENTS

COLAB_PYTHON_VERSION = "3.12"


def main():
    lock = []
    requirements = [
        "# Generated by: python colab/build.py",
        "-r ../requirements.txt",
        "-r ../manager_requirements.txt",
        "aria2p",
    ]
    for name in sorted(os.listdir(CUSTOM_NODES)):
        path = os.path.join(CUSTOM_NODES, name)
        if not os.path.isdir(path) or name == "__pycache__":
            continue
        if not os.path.isfile(os.path.join(path, ".tracking")):
            raise RuntimeError(f"{name} was not installed from the Comfy Registry, reinstall it with ComfyUI-Manager.")
        with open(os.path.join(path, "pyproject.toml"), "rb") as f:
            project = tomllib.load(f)["project"]
        # The registry stores versions as full semver, "1.23" is published as "1.23.0".
        version = project["version"] + ".0" * (2 - project["version"].count("."))
        lock.append(f"{project['name']} {version}")

        node_requirements = os.path.join(path, "requirements.txt")
        if not os.path.isfile(node_requirements):
            continue
        with open(node_requirements, encoding="utf-8") as f:
            node_lines = [l.strip() for l in f if l.strip() and not l.strip().startswith("#")]
        if node_lines:
            requirements += [f"\n# {project['name']}"] + node_lines

    with open(NODES_LOCK, "w", encoding="utf-8", newline="\n") as f:
        f.write("".join(l + "\n" for l in lock))
    with open(REQUIREMENTS, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(requirements) + "\n")
    print(f"Pinned {len(lock)} custom nodes in {NODES_LOCK}")
    print(f"Wrote {REQUIREMENTS}")

    subprocess.check_call(["uv", "pip", "compile", "--quiet", "--python-platform", "x86_64-manylinux_2_28",
                           "--python-version", COLAB_PYTHON_VERSION, REQUIREMENTS], stdout=subprocess.DEVNULL)
    print("Requirements resolve for Colab.")


if __name__ == "__main__":
    main()
